<style>
.flow-editor{max-width:1600px;margin:auto;border:1px solid #d9e4f0;border-radius:16px;overflow:hidden;background:#fff;color:#20354d;box-shadow:0 12px 32px #15315014}.flow-editor *{box-sizing:border-box}.flow-head{padding:22px 28px;background:linear-gradient(115deg,#102c50,#23578d);color:white}.flow-head h2{margin:0;color:white;font-size:28px}.flow-head p{margin:7px 0 0;color:#d9e8f7;font-size:13px}.flow-tools{display:flex;gap:8px;flex-wrap:wrap;padding:13px;background:#f5f8fc;border-bottom:1px solid #dce5ef}.flow-editor button,.flow-editor input,.flow-editor select{font:inherit}.flow-editor button{border:1px solid #cbd8e7;border-radius:8px;background:#fff;color:#244461;padding:9px 12px;font-size:13px;font-weight:700;cursor:pointer}.flow-editor button.primary{background:#20588e;color:white;border-color:#20588e}.flow-layout{display:grid;grid-template-columns:180px minmax(0,1fr)}.flow-palette{padding:14px;background:#f8fafc;border-right:1px solid #e1e8f0}.flow-palette h3{font-size:13px;color:#47617b}.flow-palette button{display:block;width:100%;margin:8px 0;text-align:left}.flow-work{padding:14px;min-width:0}.flow-canvas-wrap{overflow:auto;border:1px solid #d9e3ed;border-radius:10px;background-image:radial-gradient(#dce5ef 1px,transparent 1px);background-size:18px 18px}.flow-canvas{display:block;width:100%;min-width:700px;height:auto;touch-action:none}.flow-node{cursor:move}.flow-node .shape{stroke-width:2;filter:drop-shadow(0 2px 2px #1d38521a)}.flow-node.selected .shape{stroke:#e39a25;stroke-width:4}.flow-node text{font:700 17px Arial,sans-serif;fill:#1d3d5b;text-anchor:middle;pointer-events:none}.flow-edge{fill:none;stroke:#6485a5;stroke-width:2.2;marker-end:url(#flowArrow)}.flow-fields{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:12px;margin-top:10px;border:1px solid #dce5ef;border-radius:10px;background:#f8fafc}.flow-fields label{font-size:12px;font-weight:700}.flow-fields input[type=text]{width:220px}.flow-fields input,.flow-fields select{border:1px solid #ccd8e5;border-radius:7px;padding:8px}.flow-status{padding:10px 14px;border-top:1px solid #e1e8f0;color:#61758a;font-size:12px}.flow-note{font-size:12px;line-height:1.5;color:#687e93}@media(max-width:800px){.flow-layout{grid-template-columns:1fr}.flow-palette{display:flex;flex-wrap:wrap;gap:6px;border-right:0;border-bottom:1px solid #e1e8f0}.flow-palette h3,.flow-note{width:100%}.flow-palette button{width:auto}.flow-head{padding:18px}}@media print{.flow-tools,.flow-palette,.flow-fields,.flow-status{display:none!important}.flow-layout{display:block}.flow-canvas{min-width:0}}
</style>
<section class="flow-editor" id="procFlowEditor">
<header class="flow-head"><h2>Procurement Process Flowchart</h2><p>Create your own flowchart: add shapes, drag them around, edit labels, and connect steps.</p></header>
<div class="flow-tools">
<button type="button" class="primary" id="fcConnect">Connect selected (Shift-click 2)</button><button type="button" id="fcDelete">Delete selected</button><button type="button" id="fcSave">Save on this browser</button><button type="button" id="fcLoad">Load saved</button><button type="button" id="fcExport">Export SVG</button><button type="button" id="fcPrint">Print</button><button type="button" id="fcClear">Clear canvas</button>
</div>
<div class="flow-layout">
<aside class="flow-palette"><h3>Add a shape</h3><button type="button" data-add="process">▭ Process</button><button type="button" data-add="decision">◇ Decision</button><button type="button" data-add="start">⬭ Start / End</button><button type="button" data-add="document">▤ Document</button><p class="flow-note">Click to select. Shift-click two shapes and choose Connect. Double-click a shape to edit its text. Drag to reposition.</p></aside>
<main class="flow-work"><div class="flow-canvas-wrap"><svg class="flow-canvas" id="fcCanvas" viewBox="0 0 1200 760" role="img" aria-label="Interactive flowchart canvas"><defs><marker id="flowArrow" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#6485a5"/></marker></defs><g id="fcEdges"></g><g id="fcNodes"></g></svg></div>
<div class="flow-fields"><label for="fcText">Text</label><input id="fcText" type="text" placeholder="Selected shape label"><label for="fcType">Shape</label><select id="fcType"><option value="process">Process</option><option value="decision">Decision</option><option value="start">Start / End</option><option value="document">Document</option></select><label for="fcFill">Fill</label><input id="fcFill" type="color" value="#e5f1ff"><button type="button" class="primary" id="fcApply">Apply changes</button></div>
</main></div><div class="flow-status" id="fcStatus" role="status">Ready. Add a shape to begin.</div></section>
<script>
(function(){
var root=document.getElementById('procFlowEditor');if(!root||root.dataset.ready)return;root.dataset.ready='1';
var svg=root.querySelector('#fcCanvas'),nl=root.querySelector('#fcNodes'),el=root.querySelector('#fcEdges'),txt=root.querySelector('#fcText'),typ=root.querySelector('#fcType'),fill=root.querySelector('#fcFill'),status=root.querySelector('#fcStatus');
var nodes=[],edges=[],sel=[],next=1,drag=null,colors={process:'#e5f1ff',decision:'#fff2c7',start:'#e3f6e8',document:'#f0e8ff'},labels={process:'Process step',decision:'Decision?',start:'Start / End',document:'Document'};
function say(s){status.textContent=s}function find(id){return nodes.find(function(n){return n.id===id})}function dims(n){return n.type==='decision'?[160,90]:n.type==='start'?[160,58]:[170,72]}
function elSvg(tag,attrs){var e=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.keys(attrs||{}).forEach(function(k){e.setAttribute(k,attrs[k])});return e}
function lines(s,max){var words=String(s||'').split(/\s+/),out=[],line='';words.forEach(function(w){if((line+' '+w).trim().length>max&&line){out.push(line);line=w}else line=(line+' '+w).trim()});if(line)out.push(line);return out.slice(0,4)}
function sync(){var ids=sel.filter(function(x){return typeof x==='number'}),n=ids.length===1?find(ids[0]):null;txt.value=n?n.text:'';typ.value=n?n.type:'process';fill.value=n?n.fill:colors.process}
function render(){nl.replaceChildren();el.replaceChildren();edges.forEach(function(e){var a=find(e.from),b=find(e.to);if(!a||!b)return;var da=dims(a),db=dims(b),dx=b.x-a.x,dy=b.y-a.y,x1=a.x,y1=a.y,x2=b.x,y2=b.y;if(Math.abs(dx)>Math.abs(dy)){x1+=Math.sign(dx)*da[0]*.4;x2-=Math.sign(dx)*db[0]*.4}else{y1+=Math.sign(dy)*da[1]*.4;y2-=Math.sign(dy)*db[1]*.4}el.appendChild(elSvg('path',{class:'flow-edge',d:'M'+x1+','+y1+' L'+x2+','+y2}))});
nodes.forEach(function(n){var d=dims(n),g=elSvg('g',{class:'flow-node'+(sel.indexOf(n.id)>=0?' selected':''),'data-id':n.id}),shape;
if(n.type==='decision')shape=elSvg('polygon',{class:'shape',points:n.x+','+(n.y-d[1]/2)+' '+(n.x+d[0]/2)+','+n.y+' '+n.x+','+(n.y+d[1]/2)+' '+(n.x-d[0]/2)+','+n.y,fill:n.fill,stroke:'#c9a044'});
else if(n.type==='start')shape=elSvg('rect',{class:'shape',x:n.x-d[0]/2,y:n.y-d[1]/2,width:d[0],height:d[1],rx:d[1]/2,fill:n.fill,stroke:'#5ca878'});
else if(n.type==='document')shape=elSvg('path',{class:'shape',d:'M'+(n.x-d[0]/2)+','+(n.y-d[1]/2)+' h152 l18,18 v54 h-170 z',fill:n.fill,stroke:'#9477c5'});
else shape=elSvg('rect',{class:'shape',x:n.x-d[0]/2,y:n.y-d[1]/2,width:d[0],height:d[1],rx:12,fill:n.fill,stroke:'#6193c4'});g.appendChild(shape);
var ls=lines(n.text,n.type==='decision'?16:20),t=elSvg('text',{x:n.x,y:n.y-(ls.length-1)*10+6});ls.forEach(function(s,i){var sp=elSvg('tspan',{x:n.x,dy:i?20:0});sp.textContent=s;t.appendChild(sp)});g.appendChild(t);
g.addEventListener('pointerdown',function(ev){if(ev.button!==0)return;ev.preventDefault();ev.stopPropagation();if(ev.shiftKey)sel=sel.indexOf(n.id)>=0?sel.filter(function(x){return x!==n.id}):sel.filter(function(x){return typeof x==='number'}).concat([n.id]);else if(sel.indexOf(n.id)<0)sel=[n.id];sync();var p=point(ev);drag={id:n.id,dx:n.x-p.x,dy:n.y-p.y};try{svg.setPointerCapture(ev.pointerId)}catch(e){}render()});
g.addEventListener('dblclick',function(ev){ev.stopPropagation();sel=[n.id];sync();txt.focus();txt.select()});nl.appendChild(g)});sync()}
function point(ev){var p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;var m=svg.getScreenCTM();if(!m)return{x:0,y:0};var q=p.matrixTransform(m.inverse());return{x:q.x,y:q.y}}
root.querySelectorAll('[data-add]').forEach(function(b){b.addEventListener('click',function(){var type=b.dataset.add,off=(nodes.length%7)*15,n={id:next++,type:type,x:250+off,y:120+off,text:labels[type],fill:colors[type]};nodes.push(n);sel=[n.id];render();txt.focus();txt.select();say('Shape added. Drag it, then edit its text below.')})});
svg.addEventListener('pointermove',function(ev){if(!drag)return;var n=find(drag.id),p=point(ev);if(!n)return;n.x=Math.max(85,Math.min(1115,p.x+drag.dx));n.y=Math.max(40,Math.min(720,p.y+drag.dy));render()});svg.addEventListener('pointerup',function(){drag=null});svg.addEventListener('pointercancel',function(){drag=null});
root.querySelector('#fcApply').addEventListener('click',function(){var n=find(sel.find(function(x){return typeof x==='number'}));if(!n){say('Select one shape first.');return}n.text=txt.value.trim()||labels[typ.value];n.type=typ.value;n.fill=fill.value;render();say('Shape updated.')});
root.querySelector('#fcConnect').addEventListener('click',function(){var ids=sel.filter(function(x){return typeof x==='number'});if(ids.length!==2){say('Shift-click exactly two shapes, then click Connect selected.');return}if(edges.some(function(e){return e.from===ids[0]&&e.to===ids[1]})){say('These shapes are already connected.');return}edges.push({from:ids[0],to:ids[1]});sel=[];render();say('Connector added from first selected shape to second.')});
root.querySelector('#fcDelete').addEventListener('click',function(){var ids=sel.filter(function(x){return typeof x==='number'});nodes=nodes.filter(function(n){return ids.indexOf(n.id)<0});edges=edges.filter(function(e){return ids.indexOf(e.from)<0&&ids.indexOf(e.to)<0});sel=[];render();say('Selected shapes deleted.')});
root.querySelector('#fcSave').addEventListener('click',function(){try{localStorage.setItem('procurementFlowCreatorV1',JSON.stringify({nodes:nodes,edges:edges,next:next}));say('Saved in this browser on this device.')}catch(e){say('Browser save unavailable. Export the SVG to keep a copy.')}});
root.querySelector('#fcLoad').addEventListener('click',function(){try{var d=JSON.parse(localStorage.getItem('procurementFlowCreatorV1')||'null');if(!d){say('No saved flowchart found.');return}nodes=d.nodes||[];edges=d.edges||[];next=d.next||1;sel=[];render();say('Saved flowchart loaded.')}catch(e){say('Could not load saved flowchart.')}});
root.querySelector('#fcClear').addEventListener('click',function(){if(!confirm('Clear all shapes and connectors?'))return;nodes=[];edges=[];sel=[];render();say('Canvas cleared.')});
root.querySelector('#fcPrint').addEventListener('click',function(){window.print()});
root.querySelector('#fcExport').addEventListener('click',function(){var clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelectorAll('.selected').forEach(function(e){e.classList.remove('selected')});var url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='procurement-flowchart.svg';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);say('SVG export started.')});
render();
})();
</script>
<?php pageEnd(); ?>
